package app.repositories;

import app.Documents;
import app.common.Page;
import app.entities.Country;
import com.mongodb.client.model.Filters;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.WeakHashMap;
import org.bson.Document;
import org.springframework.dao.DataAccessException;
import org.springframework.data.domain.Sort;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;

/** Keeps countries documents in the database, through a MongoTemplate. Every write is stored at once. */
public class MongoCountryRepository implements CountryRepository {
    /** The document each entity was read from: a change writes only the fields that differ */
    private static final Map<Country, Document> LOADED = Collections.synchronizedMap(new WeakHashMap<>());

    /** The fields a change may write */
    private static final List<String> FIELDS = List.of("id", "name");

    private final MongoTemplate mongo;

    public MongoCountryRepository(MongoTemplate mongo) {
        this.mongo = mongo;
    }

    @Override
    public Optional<Country> findByDocumentId(String documentId) {
        Country found = mongo.findOne(Query.query(Criteria.where("documentId").is(documentId)), Country.class);
        return Optional.ofNullable(found == null ? null : loaded(found));
    }

    @Override
    public Page<Country> list(int offset, int limit) {
        List<Country> items = mongo.find(new Query().with(Sort.by("documentId")).skip(offset).limit(limit), Country.class).stream().map(this::loaded).toList();
        return new Page<>(items, mongo.count(new Query(), Country.class), offset, limit);
    }

    @Override
    public Optional<Country> findById(Double id) {
        Country found = mongo.findOne(Query.query(Criteria.where("id").is(id)), Country.class);
        return Optional.ofNullable(found == null ? null : loaded(found));
    }

    @Override
    public Country insert(Country entity) {
        try {
            mongo.insert(entity);
        } catch (DataAccessException error) {
            throw Documents.refusal("Country", error);
        }
        return loaded(entity);
    }

    @Override
    public Country update(Country entity) {
        Document now = Documents.of(mongo, entity);
        Document changes = Documents.changes(LOADED.get(entity), now, FIELDS);
        try {
            if (!changes.isEmpty()) mongo.execute(Country.class, (collection) -> collection.updateOne(Filters.eq("_id", now.get("_id")), changes));
        } catch (DataAccessException error) {
            throw Documents.refusal("Country", error);
        }
        return loaded(entity);
    }

    @Override
    public void delete(Country entity) {
        try {
            mongo.remove(Query.query(Criteria.where("documentId").is(entity.getDocumentId())), Country.class);
        } catch (DataAccessException error) {
            throw Documents.refusal("Country", error);
        }
    }

    /** The same entity, with what it is stored as kept to tell its changes. */
