package app.repositories;

import app.Documents;
import app.common.Page;
import app.entities.Customer;
import com.mongodb.client.model.Filters;
import com.mongodb.client.model.FindOneAndUpdateOptions;
import com.mongodb.client.model.ReturnDocument;
import java.time.Instant;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.WeakHashMap;
import org.bson.Document;
import org.bson.types.ObjectId;
import org.springframework.dao.DataAccessException;
import org.springframework.data.domain.Sort;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;

/** Keeps customers documents in the database, through a MongoTemplate. Every write is stored at once. */
public class MongoCustomerRepository implements CustomerRepository {
    /** The document each entity was read from: a change writes only the fields that differ */
    private static final Map<Customer, Document> LOADED = Collections.synchronizedMap(new WeakHashMap<>());

    /** The fields a change may write */
    private static final List<String> FIELDS = List.of("email", "name", "passwordHash", "active", "level", "address", "tags", "preferences", "extra", "deletedAt");

    private final MongoTemplate mongo;

    public MongoCustomerRepository(MongoTemplate mongo) {
        this.mongo = mongo;
    }

    @Override
    public Optional<Customer> findById(String id) {
        Customer found = mongo.findOne(Query.query(Criteria.where("id").is(id).and("deletedAt").is(null)), Customer.class);
        return Optional.ofNullable(found == null ? null : loaded(found));
    }

    @Override
    public Page<Customer> list(int offset, int limit) {
        List<Customer> items = mongo.find(Query.query(Criteria.where("deletedAt").is(null)).with(Sort.by("id")).skip(offset).limit(limit), Customer.class).stream().map(this::loaded).toList();
        return new Page<>(items, mongo.count(Query.query(Criteria.where("deletedAt").is(null)), Customer.class), offset, limit);
    }

    @Override
    public Optional<Customer> findByEmail(String email) {
        Customer found = mongo.findOne(Query.query(Criteria.where("email").is(email).and("deletedAt").is(null)), Customer.class);
        return Optional.ofNullable(found == null ? null : loaded(found));
    }

    @Override
    public Customer insert(Customer entity) {
        if (entity.getActive() == null) entity.setActive(true);
        if (entity.getLevel() == null) entity.setLevel("basic");
        if (entity.getCreatedAt() == null) entity.setCreatedAt(Instant.now());
        if (entity.getUpdatedAt() == null) entity.setUpdatedAt(Instant.now());
        try {
            mongo.insert(entity);
        } catch (DataAccessException error) {
            throw Documents.refusal("Customer", error);
        }
        return loaded(entity);
    }

    @Override
    public Customer update(Customer entity) {
        entity.setUpdatedAt(Instant.now());
        Document now = Documents.of(mongo, entity);
        Document changes = Documents.changes(LOADED.get(entity), now, FIELDS);
        if (!changes.isEmpty()) ((Document) changes.computeIfAbsent("$set", (name) -> new Document())).append("updatedAt", now.get("updatedAt"));
        try {
            if (!changes.isEmpty()) mongo.execute(Customer.class, (collection) -> collection.updateOne(Filters.eq("_id", now.get("_id")), changes));
        } catch (DataAccessException error) {
            throw Documents.refusal("Customer", error);
        }
        return loaded(entity);
    }

    @Override
    public void delete(Customer entity) {
        try {
            mongo.remove(Query.query(Criteria.where("id").is(entity.getId())), Customer.class);
        } catch (DataAccessException error) {
            throw Documents.refusal("Customer", error);
        }
    }

    @Override
    public Optional<Customer> addTag(String id, String tag) {
        if (!ObjectId.isValid(id)) return Optional.empty();
        Document change = new Document("$push", new Document("tags", mongo.getConverter().convertToMongoType(tag))).append("$set", new Document().append("updatedAt", new java.util.Date()));
        Document filter = new Document("_id", new ObjectId(id)).append("deletedAt", null);
        FindOneAndUpdateOptions after = new FindOneAndUpdateOptions().returnDocument(ReturnDocument.AFTER);
        Document changed;
        try {
            changed = mongo.execute(Customer.class, (collection) -> collection.findOneAndUpdate(filter, change, after));
        } catch (DataAccessException error) {
            throw Documents.refusal("Customer", error);
        }
        return Optional.ofNullable(changed).map((document) -> loaded(mongo.getConverter().read(Customer.class, document)));
    }

    @Override
    public Optional<Customer> removeTag(String id, String tag) {
        if (!ObjectId.isValid(id)) return Optional.empty();
        Document change = new Document("$pull", new Document("tags", mongo.getConverter().convertToMongoType(tag))).append("$set", new Document().append("updatedAt", new java.util.Date()));
        Document filter = new Document("_id", new ObjectId(id)).append("deletedAt", null);
        FindOneAndUpdateOptions after = new FindOneAndUpdateOptions().returnDocument(ReturnDocument.AFTER);
        Document changed;
        try {
            changed = mongo.execute(Customer.class, (collection) -> collection.findOneAndUpdate(filter, change, after));
        } catch (DataAccessException error) {
            throw Documents.refusal("Customer", error);
        }
        return Optional.ofNullable(changed).map((document) -> loaded(mongo.getConverter().read(Customer.class, document)));
    }

    /** The same entity, with what it is stored as kept to tell its changes. */
