    static Customer addCustomer(UnitOfWork uow, int n) {
        Customer entity = newCustomer(n);
        return uow.customers().insert(entity);
    }

    /** A valid Customer.Address. */
    static Customer.Address newCustomerAddress(int n) {
        Customer.Address item = new Customer.Address();
        item.setStreet("street-" + n);
        item.setCity("city-" + n);
        item.setZipCode("zipcode-" + n);
        item.setLocation(newCustomerAddressLocation(n));
        return item;
    }

    /** A valid Customer.Address.Location. */
    static Customer.Address.Location newCustomerAddressLocation(int n) {
        Customer.Address.Location item = new Customer.Address.Location();
        item.setType("Point");
        item.setCoordinates(new java.util.ArrayList<>());
        return item;
    }

    /** A valid Customer.Preferences. */
    static Customer.Preferences newCustomerPreferences(int n) {
        Customer.Preferences item = new Customer.Preferences();
        item.setTheme("theme-" + n);
        item.setNewsletter(true);
        return item;
    }

    /** A valid Product that is not stored yet; n makes its unique values differ. */
    static Product newProduct(int n) {
        Product entity = new Product();
        entity.setSku("sku-" + n);
        entity.setTitle("title-" + n);
        entity.setPrice(new BigDecimal((n % 10000) + ".50"));
        entity.setStock(n + 0.5);
        entity.setReference(UUID.fromString(String.format("00000000-0000-4000-8000-%012d", n)));
        entity.setPicture(new byte[] { (byte) n });
        entity.setRelated(new java.util.ArrayList<>());
        return entity;
    }

    /** A stored Product. */
    static Product addProduct(UnitOfWork uow, int n) {
        Product entity = newProduct(n);
        return uow.products().insert(entity);
    }

    /** A valid Order that is not stored yet; n makes its unique values differ. */
    static Order newOrder(int n) {
        Order entity = new Order();
        entity.setNumber(n + 0.5);
        entity.setYear(n + 0.5);
        entity.setLines(new java.util.ArrayList<>(List.of(newOrderLine(n))));
        entity.setNotes(new java.util.ArrayList<>(List.of(newOrderNote(n))));
        return entity;
    }

    /** A stored Order, with the rows it points to. */
    static Order addOrder(UnitOfWork uow, int n) {
        Customer parent0 = addCustomer(uow, n);
        Order entity = newOrder(n);
        entity.setCustomer(parent0.getId());
        return uow.orders().insert(entity);
    }

    /** A valid Order.Line. */
    static Order.Line newOrderLine(int n) {
        Order.Line item = new Order.Line();
        item.setProduct(String.format("%024x", n));
        item.setQuantity(1 + n + 0.5);
        item.setPrice(new BigDecimal((n % 10000) + ".50"));
        item.setStatus("pending");
        return item;
    }

    /** A valid Order.Note. */
    static Order.Note newOrderNote(int n) {
        Order.Note item = new Order.Note();
        item.setText("text-" + n);
        item.setAt(Instant.parse(String.format("2026-01-%02dT12:00:00Z", n % 28 + 1)));
        return item;
    }

    /** A valid Country that is not stored yet; n makes its unique values differ. */
    static Country newCountry(int n) {
        Country entity = new Country();
        entity.setDocumentId("id-" + n);
        entity.setId(n + 0.5);
        entity.setName("name-" + n);
        return entity;
    }

    /** A stored Country. */
    static Country addCountry(UnitOfWork uow, int n) {
        Country entity = newCountry(n);
        return uow.countries().insert(entity);
    }
