package app;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import app.entities.Order;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

/** Tests of the "orders" table. */
class OrderTest {
    /** The repositories over the test database, opened empty for every test */
    private MongoUnitOfWork uow;

    @BeforeEach
    void open() {
        uow = new MongoUnitOfWork(TestDatabase.open());
    }

    @Nested
    class Repository {

        @Test
        void isStoredAndReadBack() {
            Order stored = Factories.addOrder(uow, 1);
            Order found = uow.orders().findById(stored.getId()).orElseThrow();
            assertEquals(stored.getId(), found.getId());
            assertTrue(uow.orders().findByYearAndNumber(stored.getYear(), stored.getNumber()).isPresent());
            if (stored.getCustomer() != null) assertEquals(1, uow.orders().listByCustomer(stored.getCustomer()).size());
        }

        @Test
        void listsRowsByKey() {
            Factories.addOrder(uow, 1);
            Factories.addOrder(uow, 2);
            var page = uow.orders().list(0, 1);
            assertEquals(2, page.total());
            assertEquals(1, page.items().size());
        }

        @Test
        void addsAndRemovesOneItemOfLines() {
            Order stored = Factories.addOrder(uow, 1);
            int before = stored.getLines() == null ? 0 : stored.getLines().size();
            Order.Line item = Factories.newOrderLine(7);
            Order added = uow.orders().addLine(stored.getId(), item).orElseThrow();
            assertEquals(before + 1, added.getLines().size());
            Order removed = uow.orders().removeLine(stored.getId(), added.getLines().get(before).getId()).orElseThrow();
            assertEquals(before, removed.getLines().size());
        }

        @Test
        void addsAndRemovesOneItemOfNotes() {
            Order stored = Factories.addOrder(uow, 1);
            int before = stored.getNotes() == null ? 0 : stored.getNotes().size();
            Order.Note item = Factories.newOrderNote(7);
            Order added = uow.orders().addNote(stored.getId(), item).orElseThrow();
            assertEquals(before + 1, added.getNotes().size());
            Order removed = uow.orders().removeNote(stored.getId(), added.getNotes().get(before).getId()).orElseThrow();
            assertEquals(before, removed.getNotes().size());
        }

        @Test
        void isDeleted() {
            Order stored = Factories.addOrder(uow, 1);
            uow.orders().delete(stored);
            assertTrue(uow.orders().findById(stored.getId()).isEmpty());
        }
    }
}

